Table(
    {
        DisplayName: "Ava Chen",
        Mail: "ava.chen@example.com",
        JobTitle: "Operations Lead"
    },
    {
        DisplayName: "Marcus Hale",
        Mail: "marcus.hale@example.com",
        JobTitle: "Field Supervisor"
    },
    {
        DisplayName: "Priya Raman",
        Mail: "priya.raman@example.com",
        JobTitle: "Compliance Analyst"
    },
    {
        DisplayName: "Tom Okafor",
        Mail: "tom.okafor@example.com",
        JobTitle: "Project Manager"
    },
    {
        DisplayName: "Nina Sorensen",
        Mail: "nina.sorensen@example.com",
        JobTitle: "Safety Officer"
    },
    {
        DisplayName: "Luis Ortega",
        Mail: "luis.ortega@example.com",
        JobTitle: "Scheduler"
    }
)

If(!IsBlank(cmbSeCc.SearchText), cmbSeCc.SearchText, cmbSeTo.SearchText)
// ONE OUTPUT FOR TWO PICKERS. Only one of them has focus at a time, so
// Cc winning when its box is not empty is enough to tell the host which
// search the results are for. Two separate outputs would be tidier and
// would double the API for a case nobody hits.

Set(_cmpSePriority, "");
Set(_cmpSeShowCc, false);
Set(_cmpSeTouched, false);
Set(_cmpSeNote, "");
Set(_cmpSeSubject, cmpSendEmail.DefaultSubject);
Set(_cmpSeTo, "");
Set(_cmpSeCc, "");
Set(_cmpSeBody, "");
Set(_cmpSeCount, 0);
Reset(cmbSeTo);
Reset(cmbSeCc);
Reset(txtSeSubject);
Reset(txtSeNote)
// A COMPONENT HAS NO OnHidden, so nothing in here can notice it stopped
// being visible. The host calls Reset() on both close paths, and the
// usage notes say so in as many words.
//
// The note is cleared rather than preserved. A surviving draft is a good
// idea for a mail composed over several sittings and a bad one for a per
// record notification, where the previous record's note reappearing is a
// leak between records.
//
// _cmpSeTouched gates the validation message so a dialog does not open
// already showing an error about a field nobody has reached yet.

cmpSendEmail.OnCancel()
// CLICK OUTSIDE TO DISMISS. Disabled rather than guarded while
// Busy, so a mis-click during a send cannot tear the dialog down
// underneath an in flight request.
//
// Classic/Button@2.2.0 has NO AccessibleLabel property; Studio
// rejects it with PA2108. TabIndex -1 is therefore the whole
// mitigation: the scrim never takes keyboard focus, so it is
// never the thing announced with nothing to say. Tooltip would
// name it and is supported, but a tooltip on a control covering
// the whole screen fires on every hover over the backdrop.
// btnSeClose and btnSeCancel are the labelled escapes.

Min(
    conSePriority.Height
    + lblSeToLabel.Height + 36 + lblSeToSummary.Height
    + conSeCcRow.Height
    + lblSeSubjLabel.Height + 36
    + lblSeNoteLabel.Height + 96 + lblSeCounter.Height
    + 9 * Self.LayoutGap + Self.PaddingTop + Self.PaddingBottom,
    App.Height - conSeHeader.Height - conSeFooter.Height - 96
)
// TEN CHILDREN, SO NINE GAPS. Hand counted, and the one thing here
// that silently rots when a field is added. It fails SAFE: an
// undercount only grows the scrollbar LayoutOverflowY already
// provides, it never clips.
//
// App.Height, NOT Parent.Height. Parent is conSeCard, whose height
// is the sum of this container and its siblings, so reading Parent
// here is a circular reference that Studio will not catch for you.

If(
    cmpSendEmail.Config.ShowPriority,
    32 + Self.PaddingTop + Self.PaddingBottom,
    0
)
// THE PADDING IS ADDED BACK INTO THE HEIGHT rather than left
// as a bare 32. The buttons inside are 32 tall, so a fixed 32
// on a container that now pads 4 top and bottom clips them by
// 8. Reading Self.PaddingTop keeps the two in step if the
// padding is ever retuned.

If(
    _cmpSePriority = "Urgent",
    "Urgent, selected. Select again to clear.",
    "Mark this message urgent"
)
// THE SELECTED STATE IS IN THE TOOLTIP because fill
// colour alone is not a state a screen reader can read,
// and Classic/Button has no AccessibleLabel.

Set(_cmpSePriority, If(_cmpSePriority = "Urgent", "", "Urgent"))
// TAPPING THE LIT TAG CLEARS IT. There is no none option
// because the three tags are their own toggle group, and
// a fourth button reading none is a fourth thing to read.

ThisItem.DisplayName & "   -   " & ThisItem.Mail
// THIS ONE FORMULA IS WHY THE CONTROL IS MODERN AND THE REST
// OF THE COMPONENT IS CLASSIC. Classic/ComboBox picks its
// display columns from DisplayFields, and the Single, Double
// or Person TEMPLATE that decides how those columns are laid
// out is not a Property at all. In the pa.yaml v3.0 schema a
// control instance takes Control, Variant, MetadataKey,
// Layout, IsLocked, Group, Properties and Children, and the
// template lives up at Layout, a sibling of Control, NOT under
// Properties. Nothing written under Properties can reach it,
// which is why a pasted classic picker always lands on Single
// and has to be repaired by hand in the Data pane.
//
// Microsoft removed that mechanism outright on the modern
// control: Fields was REPLACED by ItemDisplayText, a Power Fx
// formula. A formula is a Property, so it survives a paste.
// There is no template to lose and no manual step to document.

true
// WRITTEN EXPLICITLY on both pickers even though the modern
// default is already true, because the send loop walks
// SelectedItems and a picker silently capped at one recipient
// is not a failure anyone notices until the mail goes out.

true
// SearchText UPDATES ON A PAUSE, NOT PER KEYSTROKE. A host
// wired to a live directory search would otherwise fire one
// connector call per character, and Office365Users throttles
// per user per connection. Typing a five letter name is five
// round trips and the fifth is the only one anybody wanted.

If(
    _cmpSeTouched && IsEmpty(Self.SelectedItems),
    ValidationState.Error,
    ValidationState.None
)
// Self.SelectedItems, NOT cmbSeTo.SelectedItems. A control
// naming itself inside its own property never resolves and
// comes back blank in silence. The classic version of this
// control had exactly that bug in its BorderColor.
//
// IsEmpty, NOT IsBlank: SelectedItems is a TABLE, and a table
// with no rows is empty and never blank, so IsBlank returns
// false on an untouched picker and the validation never fires.
//
// ValidationState replaces the hand rolled red BorderColor.
// The control draws its own error affordance, which stays
// correct under a theme the component has never seen.

With(
    {
        picked: CountRows(cmbSeTo.SelectedItems),
        nomail: CountRows(Filter(cmbSeTo.SelectedItems, IsBlank(Mail)))
    },
    If(
        picked = 0,
        If(_cmpSeTouched, "Pick at least one recipient.", "Nobody selected yet."),
        picked & If(picked = 1, " recipient", " recipients")
        & If(
            nomail > 0,
            "   |   " & nomail & " with no address, they will be skipped",
            ""
        )
    )
)
// THE NO ADDRESS COUNT IS SURFACED BEFORE THE SEND, not after.
// A directory table can carry rows with a blank Mail, and those
// get dropped when the address string is built. Silently
// dropping a recipient the sender watched themselves pick is
// the worst outcome available.

Set(_cmpSeShowCc, !_cmpSeShowCc);
If(!_cmpSeShowCc, Reset(cmbSeCc))
// HIDING CC CLEARS IT. Leaving a hidden picker populated
// means sending to people the sender can no longer see,
// which is the worst way to be surprised by an email.

If(
    cmpSendEmail.Busy || cmpSendEmail.Config.LockSubject,
    DisplayMode.View,
    DisplayMode.Edit
)
// View, NOT Disabled, when the subject is locked. Disabled
// greys the text to the point of being hard to read, and a
// fixed subject is information the sender still needs.

""
// WRITTEN OUT rather than left to the control default, which
// is the literal string "Text input". Omitting it ships a
// dialog whose message box arrives pre-filled with placeholder
// text that a hurried sender will mail to somebody.

If(
    Len(txtSeNote.Text) >= cmpSendEmail.Config.MaxNote,
    RGBA(220, 38, 38, 1),
    If(
        Len(txtSeNote.Text) > cmpSendEmail.Config.MaxNote * 0.9,
        RGBA(217, 119, 6, 1),
        If(
            cmpSendEmail.Config.Theme = "dark",
            RGBA(100, 116, 139, 1),
            RGBA(148, 163, 184, 1)
        )
    )
)
// THE COUNTER WARMS UP BEFORE IT MATTERS. Amber at ninety
// percent, red at the cap, which is where MaxLength stops
// accepting keystrokes with no other feedback at all.

With(
    { n: CountRows(cmbSeTo.SelectedItems) },
    If(
        cmpSendEmail.Busy,
        "Sending",
        If(n = 0, "Send", "Send to " & n)
    )
)
// THE BUTTON COUNTS THE RECIPIENTS. Reading Send to 7 just
// before committing is the cheapest possible guard against the
// mail going wider than intended.

Set(_cmpSeTouched, true);
Clear(colCmpSeTo);
Collect(
    colCmpSeTo,
    ForAll(
    cmbSeTo.SelectedItems As p, { Addr: Lower(Trim(p.Mail)) }
    )
);
Clear(colCmpSeCc);
If(
    _cmpSeShowCc && cmpSendEmail.Config.ShowCc,
    Collect(
        colCmpSeCc,
        ForAll(
        cmbSeCc.SelectedItems As c, { Addr: Lower(Trim(c.Mail)) }
        )
    )
);
Set(
    _cmpSeTo,
    Concat(Distinct(Filter(colCmpSeTo, !IsBlank(Addr)), Addr), Value, ";")
);
Set(
    _cmpSeCc,
    Concat(
        Distinct(
            Filter(
                colCmpSeCc As x,
                !IsBlank(x.Addr) && IsBlank(LookUp(colCmpSeTo, Addr = x.Addr))
            ),
            Addr
        ),
        Value,
        ";"
    )
);
Set(
    _cmpSeCount,
    CountRows(Distinct(Filter(colCmpSeTo, !IsBlank(Addr)), Addr))
);
Set(_cmpSeNote, Trim(txtSeNote.Text));
Set(
    _cmpSeSubject,
    If(IsBlank(_cmpSePriority), "", _cmpSePriority & " - ")
    & Trim(txtSeSubject.Text)
);
Set(
    _cmpSeBody,
    With(
        {
            acc: If(
                IsBlank(cmpSendEmail.Config.Accent),
                "#3B82F6",
                cmpSendEmail.Config.Accent
            ),
            head: Trim(txtSeSubject.Text)
        },
        With(
            {
                badge: Switch(
                    _cmpSePriority,
                    "Urgent", "#DC2626",
                    "Reminder", "#D97706",
                    acc
                ),
                safeHead: Substitute(
                    Substitute(
                        Substitute(head, "&", "&amp;"),
                        "<",
                        "&lt;"
                    ),
                    ">",
                    "&gt;"
                ),
                safeNote: Substitute(
                    Substitute(
                        Substitute(
                            Substitute(_cmpSeNote, "&", "&amp;"),
                            "<",
                            "&lt;"
                        ),
                        ">",
                        "&gt;"
                    ),
                    Char(10),
                    "<br>"
                ),
                safeSig: Substitute(
                    Substitute(
                        Substitute(cmpSendEmail.Signature, "&", "&amp;"),
                        "<",
                        "&lt;"
                    ),
                    ">",
                    "&gt;"
                )
            },
            "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' bgcolor='#F1F5F9' style='background-color:#F1F5F9;padding:24px 12px;'><tr><td align='center'>"
            & "<table role='presentation' width='600' cellpadding='0' cellspacing='0' border='0' bgcolor='#FFFFFF' style='width:600px;max-width:600px;background-color:#FFFFFF;border:1px solid #E2E8F0;border-radius:12px;font-family:Segoe UI,Helvetica,Arial,sans-serif;'>"
            & "<tr><td bgcolor='" & acc & "' style='height:4px;line-height:4px;font-size:0;background-color:" & acc & ";'>&nbsp;</td></tr>"
            & "<tr><td style='padding:24px 24px 8px 24px;'>"
            & If(
                IsBlank(_cmpSePriority),
                "",
                "<span style='display:inline-block;padding:4px 11px;border-radius:999px;background-color:"
                & badge
                & ";color:#FFFFFF;font-size:11px;font-weight:600;letter-spacing:0.5px;'>"
                & Upper(_cmpSePriority)
                & "</span><br><br>"
            )
            & "<div style='font-size:20px;font-weight:600;color:#0F172A;line-height:1.3;'>"
            & safeHead
            & "</div></td></tr>"
            & If(
                IsBlank(cmpSendEmail.ContextHtml),
                "",
                "<tr><td style='padding:8px 24px 0 24px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr><td bgcolor='#F8FAFC' style='background-color:#F8FAFC;border-left:3px solid "
                & acc
                & ";border-radius:6px;padding:14px 16px;font-size:13px;color:#334155;line-height:1.6;'>"
                & cmpSendEmail.ContextHtml
                & "</td></tr></table></td></tr>"
            )
            & If(
                IsBlank(safeNote),
                "",
                "<tr><td style='padding:20px 24px 4px 24px;font-size:15px;color:#0F172A;line-height:1.65;'>"
                & safeNote
                & "</td></tr>"
            )
            & If(
                IsBlank(safeSig),
                "",
                "<tr><td style='padding:20px 24px 24px 24px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr><td style='border-top:1px solid #E2E8F0;padding-top:14px;font-size:12px;color:#64748B;line-height:1.5;'>"
                & safeSig
                & "</td></tr></table></td></tr>"
            )
            & "</table></td></tr></table>"
        )
    )
    // A REAL EMAIL TEMPLATE, AND NO FLOW NEEDED FOR IT.
    // Office365Outlook.SendEmailV2 takes an HTML body straight
    // from Canvas. The earlier version was already HTML, just
    // four bold tags and some line breaks.
    //
    // TABLES, NOT DIVS, AND INLINE STYLES ONLY. Outlook on
    // Windows renders mail through WORD, not a browser engine:
    // no flexbox, no grid, no <style> block, no external CSS,
    // no web fonts. A div layout that looks perfect in Gmail
    // collapses into one unstyled column there, and Outlook is
    // the client this audience actually reads mail in. bgcolor
    // is written alongside background-color for the same reason.
    //
    // SINGLE QUOTED HTML ATTRIBUTES. Double quotes would each
    // need doubling inside a Power Fx string and a template this
    // size becomes unreadable. HTML accepts single quotes and
    // every mail client honours them. Same trick the SVG strings
    // in cmpChips use.
    //
    // border-radius and the pill badge DEGRADE to square corners
    // in Outlook desktop. That is the intended floor: nothing is
    // lost except the corners.
    //
    // THREE SLOTS, DIFFERENT CONTRACTS. safeNote and safeSig are
    // escaped, because the note is typed by a user and Signature
    // is documented as plain text. ContextHtml is injected RAW
    // because it is documented as the host's own markup, which
    // is what makes a record summary table possible at all. That
    // asymmetry IS the contract.
    //
    // 600px is the conventional email width and has nothing to
    // do with the 600 that keeps appearing on the instance.
);
If(
    IsBlank(_cmpSeTo),
    Notify(
        "Nobody you picked has an email address. Nothing was sent.",
        NotificationType.Error
    ),
    cmpSendEmail.OnSend()
)
// THE COMPONENT DOES NOT SEND. It builds every output and
// raises OnSend, and the host owns the mail action. That is
// what lets this drop into any app with no connector, and it
// means the same dialog works over Outlook, a flow, SMTP or a
// custom connector without touching a line in here.
//
// THE NOTE AND SUBJECT ARE READ FROM THE CONTROLS, not from a
// variable kept in step by OnChange. A classic text input
// raises OnChange on blur, so typing and going straight to Send
// in one motion is a real race that loses the last edit.
//
// THE NOTE IS HTML ESCAPED. The body is markup, so a note
// containing < or > or & would otherwise render as tags in the
// recipient's inbox. Ampersand is substituted FIRST; doing it
// last would re-escape the ampersands that &lt; and &gt; just
// introduced and every bracket would arrive as &amp;lt;. Line
// breaks are converted after escaping so <br> survives.
//
// ContextHtml is NOT escaped, deliberately. It is the host's
// own markup. Anything user-typed inside it is the host's to
// escape, and the property description says so.
//
// BLANK ADDRESSES ARE FILTERED OUT. A directory table can carry
// rows with no Mail, and Concat would turn those into ";;",
// which most mail actions reject for the whole send. If
// filtering leaves nothing, OnSend never fires.
//
// CC IS DEDUPED AGAINST TO, not just against itself, so nobody
// on both lines gets two copies.
//
// PROJECTED WITH ForAll BUILDING A RECORD, not ShowColumns and
// RenameColumns. Those take a column NAME, and whether it is
// written bare or quoted depends on an app level setting, so
// the same formula is valid in one app and rejected in the next.
